SELECT jsonb_build_object('orders_wrong_organization',(SELECT count(*) FROM public.neroxa_orders o LEFT JOIN public.neroxa_system_instances i ON i.id=o.instance_id WHERE i.id IS NULL OR i.organization_id IS DISTINCT FROM o.organization_id),'items_wrong_instance',(SELECT count(*) FROM public.neroxa_order_items x JOIN public.neroxa_orders o ON o.id=x.order_id JOIN public.neroxa_storefront_products p ON p.id=x.product_id WHERE p.instance_id<>o.instance_id),'items_missing_order',(SELECT count(*) FROM public.neroxa_order_items x LEFT JOIN public.neroxa_orders o ON o.id=x.order_id WHERE o.id IS NULL),'history_missing_order',(SELECT count(*) FROM public.neroxa_order_status_history h LEFT JOIN public.neroxa_orders o ON o.id=h.order_id WHERE o.id IS NULL),'total_mismatch',(SELECT count(*) FROM public.neroxa_orders WHERE total<>subtotal+delivery_fee),'item_subtotal_mismatch',(SELECT count(*) FROM public.neroxa_orders o WHERE subtotal IS DISTINCT FROM (SELECT sum(line_total) FROM public.neroxa_order_items x WHERE x.order_id=o.id)),'ambiguous_settings_instance',(SELECT count(*) FROM public.neroxa_storefront_settings s WHERE (SELECT count(*) FROM public.neroxa_system_instances i WHERE i.organization_id=s.organization_id)<>1),'ambiguous_zones_instance',(SELECT count(*) FROM public.neroxa_storefront_delivery_zones s WHERE (SELECT count(*) FROM public.neroxa_system_instances i WHERE i.organization_id=s.organization_id)<>1),'platform_auth_orphans',(SELECT count(*) FROM public.neroxa_platform_members m LEFT JOIN auth.users u ON u.id=m.user_id WHERE u.id IS NULL),'org_auth_orphans',(SELECT count(*) FROM public.neroxa_organization_members m LEFT JOIN auth.users u ON u.id=m.user_id WHERE u.id IS NULL),'invalid_instance_enum',(SELECT count(*) FROM public.neroxa_system_instances WHERE status NOT IN ('PROVISIONING','ACTIVE','SUSPENDED','ARCHIVED')),'invalid_domain_enum',(SELECT count(*) FROM public.neroxa_system_domains WHERE status NOT IN ('PENDING','VERIFYING','VERIFIED','FAILED','DISABLED')),'products_precision_loss',(SELECT count(*) FROM public.neroxa_storefront_products WHERE price IS DISTINCT FROM price::numeric(12,2)::numeric),'zones_precision_loss',(SELECT count(*) FROM public.neroxa_storefront_delivery_zones WHERE delivery_fee IS DISTINCT FROM delivery_fee::numeric(12,2)::numeric OR minimum_order IS DISTINCT FROM minimum_order::numeric(12,2)::numeric)) AS summary;
